*Define macro filenames;
%let download_link=copycat.viewer_filer_qtr;
%let filer_list=filer_list;
%let downloader_list=downloader_list;

proc sql; create table downloader_list as select distinct downloader_mgrno
from &download_link; quit;
proc sql; create table filer_list as select distinct filer_mgrno
from &download_link; quit;

proc sql; create table copy7 as select  a.*,b.filer_FB,b.downloader_FB  from copy6 as a 
left join copycat.copycat_fb as b  
on a.filer=b.filer and a.downloader=b.downloader and a.rdate=b.rdate
order by filer,downloader,rdate; quit;

*Merge with LS dataset;
proc sql; create table copy8 as select  a.*,b.filer_LS,b.downloader_LS  from copy7 as a 
left join copycat.copycat_ls as b  
on a.filer=b.filer and a.downloader=b.downloader and a.rdate=b.rdate
order by filer,downloader,rdate; quit;

*Part 1: FB stocks;
*The dataset FB12 can be created with SAS code "Copycat_CopycattingActivity";
data FB; set FB12; run;

*The dataset matched_companyret is based on four commercial databases, 
including Lipper TASS, Eurekahedge, Hedge Fund Research, and Morningstar;
*We are unable to share the dataset but provide below code for the interested readers;

*Part 1: Copycat sophistication (Table 6, Table 7 Column 1, Table 11 Panel C);

%let hf_ret=copycat.matched_companyret;
%let downloader_ret=downloader_FBLS_ret;*The dataset downloader_FBLS_ret can be created with SAS code "Copycat_StockPerformance";
%let quarterly_ret=qret;

*Part 2: Research Intensity (Table 7 Column 2);

%let hf_ret=copycat.matched_companyret;
%let res_set=copycat.research_intensity;
%let res_var=Downloads_KQ;

proc sql;
create table HF_list as select  distinct mgrno  from  &hf_ret;
quit;

*get filer sample which can be matched to union hedge fund database;
*The dataset copy12 can be created with SAS code "Copycat_CopycattingActivity";
proc sql; create table Copycat_filer1 as select *   from HF_list as a 
left join copy12 as b  on a.mgrno=b.filer order by filer,downloader,rdate; quit;

*get research intensity and sort downloaders into groups;
proc sql; create table Copycat_down1 as select distinct a.rdate,a.downloader,b.&res_var  from  Copycat_filer1 as a
left join &res_set as b  
on a.downloader=b.mgrno and intck('qtr',a.rdate,b.qdate)=1; quit;

*The confidential treatment data are for hedge fund companies, we thus limit the sample to hedge fund filers;
*The datasets mgrno_hedgefund and confidential are obtained from the authors of Agarwal, Jiang, Tang, and Yang (2013, JF);
proc sql; create table copy13 as select  *  from copycat.mgrno_hedgefund as a 
left join copy12 as b on a.mgrno=b.filer; quit;

*get confidential filer and corresponding rdate;
proc sql;
create table conf1 as select  a.*,b.hdate,b.interval  from copy13 as a 
left join copycat.confidential as b  
on a.filer=b.mgrno and a.rdate=b.hdate;

