*Merge with risk pricing factors;
proc sql;
create table Port3 as select a.*,b.mktrf*100 as mktrf,b.rf*100 as rf,
b.hml*100 as hml,b.smb*100 as smb,b.umd*100 as umd,1 as cons
from Port2 as a left join ff.factors_monthly as b  
on intck('month',a.MED,b.date)=0 order by Portfolio,MED; quit;

*create stock level bid ask spread using CRSP DSF file;
proc sort data=crsp.dseall(keep= permno  date shrcd EXCHCD siccd) out=dseall nodupkey;
where year(date) between &beg_year and &end_year and shrcd in (10, 11); by permno date; run;

proc sql; create table dsf1 
as select distinct date, permno, prc, ret, shrout, VOL, BIDLO, ASKHI, BID, ASK
from crsp.dsf
where year(date) between &beg_year and &end_year; quit;

by rdate filer downloader descending downloader_LS; run;

proc sort data=LSF1 out=LSF2(drop=permno) nodupkey;
by rdate file downloader; run;

*Define macro filenames;
%let download_link=copycat.viewer_filer_qtr_abelnoser;
%let filer_list=filer_list_abelnoser;
%let downloader_list=downloader_list_abelnoser;
%let downloader_date=downloader_date_abelnoser;
%let downloader_trades=copycat.downloader_trades_abelnoser;
%let downloader_filer_trades=copycat.downloader_filer_trades_abelnoser;

proc sql; create table FB12 as select  a.*,b.trade as valid_trade 
from FB11 as a left join &downloader_filer_trades as b  
on a.filer_mgrno=b.filer_mgrno and a.downloader_mgrno=b.downloader_mgrno 
and a.permno=b.permno and a.rdate=b.rdate where b.trade^=-1; quit;

data download_link; set &download_link; run;

proc sort data=download_link nodupkey;
by rdate filer_mgrno downloader_mgrno; run;

proc sql; create table FB13 as select  a.*,b.download  
from FB12 as a left join download_link as b  
on a.filer_mgrno=b.filer_mgrno and a.downloader_mgrno=b.downloader_mgrno 
and a.rdate=b.rdate; quit;

proc export data=Port3
outfile= ".../Copycat/&Portfolio..DTA" 
dbms=DTA replace; run;

%let hf_ret=copycat.matched_companyret;
%let downloader_ret=downloader_FBLS_ret;*The dataset downloader_FBLS_ret can be created with SAS code "Copycat_StockPerformance";
%let quarterly_ret=qret;

proc sql; create table HF_list as select  distinct mgrno  from  &hf_ret; quit;

*get filer sample which can be matched to union hedge fund database;
*The dataset copy12 can be created with SAS code "Copycat_CopycattingActivity";
proc sql; create table Copycat_filer1 as select *  from HF_list as a 
left join copy12 as b on a.mgrno=b.filer
order by filer,downloader,rdate; quit;

*get sophistication of downloaders based on the copycat returns in the past two years;
proc sql; create table downloader_Copycat_ret as select  a.rdate,a.downloader,b.&quarterly_ret as qret  from &downloader_ret as a 
left join &downloader_ret as b  
on a.downloader=b.downloader and 1<=intck('qtr',b.rdate,a.rdate)<=8
order by rdate,downloader; quit;

proc sql;
create table downloader_FBLS_ret as select rdate,downloader
from &FB_ret as a union select rdate,downloader
from &LS_ret as b; quit;

proc sql;
create table downloader_FBLS_ret as select  a.*,b.qret as fb_ret,c.qret as ls_ret
from downloader_FBLS_ret as a 
left join &FB_ret as b  
on a.rdate=b.rdate and a.downloader=b.downloader
left join &LS_ret as c 
on a.rdate=c.rdate and a.downloader=c.downloader
order by rdate,downloader; quit;

create table Holdings as
select a.rdate, a.mgrno, a.first_report, a.last_report, a.permno,
  a.shares*b.cfacshr as shares_adj format comma12. label = "Adjusted Shares Held"
from Holdings_v2 as a, price as b
where a.permno=b.permno and a.fdate = b.qdate;
quit;

*create stock level bid ask spread using CRSP DSF file;
proc sort data=crsp.dseall(keep= permno  date shrcd EXCHCD siccd) out=dseall nodupkey;
where year(date) between &beg_year and &end_year and shrcd in (10, 11); by permno date; run;

proc sql; create table dsf1 
as select distinct date, permno, prc, ret, shrout, VOL, BIDLO, ASKHI, BID, ASK
from crsp.dsf
where year(date) between &beg_year and &end_year; quit;

*Part 1. Thomson 13F and CRSP data on WRDS;
