*Part 1:Subsequent return on the FB stocks;
proc sql; create table FB13 as select distinct rdate,downloader from FB12; quit;

%let input=copycat.research_intensity;
%let sortvar=Downloads_KQ;
%let group=2;

*high research intensity (RI) group;
%let focal_group=1;
%let save_as=fb_high_ri;

