left join &input as b on a.downloader=b.mgrno and intck('qtr',a.rdate,b.qdate)=1
order by rdate,downloader; quit;

proc rank data=FB14 out=FB15 groups=&Group; by rdate; var &sortvar; run;

proc sql;
create table LS12 as select  a.*,b.trade as valid_trade 
from LS11 as a left join &downloader_filer_trades as b  
on a.filer_mgrno=b.filer_mgrno and a.downloader_mgrno=b.downloader_mgrno 
and a.permno=b.permno and a.rdate=b.rdate where b.trade^=1; quit;


*Get CRSP Prices, Returns, and Adjustment Factors from MSF Dataset 
and Since Thomson 13-F is Quarterly (FDATE & RDATE) 
Align CRSP month-end Dates and keep Quarter Ends;    
data price; format QDATE date9.;
set crsp.msf (keep=permno date cfacpr cfacshr shrout prc ret);
where date between "&begdate"d and "&enddate"d;
QDATE = INTNX('QTR',date,0,'E');
P = abs(prc)/cfacpr;

*Keep First Vintage with Holdings Data for Each RDATE-MGRNO Combinations;
proc sql;
create table First_Vint
as select distinct rdate, fdate, mgrno, mgrname
from tfn.s34type1
group by mgrno, rdate
having fdate=min(fdate)
order by mgrno, rdate;
quit;

*Extract Holdings and Adjust Shares Held;
*FDATE -Vintage Date- is used in Shares' Adjustment;
data Holdings_v1 / view=Holdings_v1;
merge First_Vint(in=a drop=mgrname)
  tfn.s34type3(in=b drop=type sole shared no);
by fdate mgrno;
if a and b and shares>0;
run;

*Map TR-13F's Historical CUSIP to CRSP Unique Identifier PERMNO;

proc sql;
create view Holdings_v2 as
select distinct a.rdate, a.fdate, a.mgrno,
        a.first_report, a.last_report, b.permno, a.shares
from Holdings_v1 as a,
   (select distinct ncusip, permno from crsp.msenames
    where not missing(ncusip)) as b
    where a.cusip=b.ncusip;
quit;

data FB12; set FB11;
if download=. then download=0;
if robot=. then robot=0;
if filer_mgrno^=. and downloader_mgrno^=.;
if "31Dec2002"d<=rdate<="31Mar2017"d;
rename filer_mgrno=filer downloader_mgrno=downloader next_FB=downloader_FB;
run;

data LS12; set LS11;
if download=. then download=0;
if robot=. then robot=0;
if filer_mgrno^=. and downloader_mgrno^=.;
if "31Dec2002"d<=rdate<="31Mar2017"d;
rename filer_mgrno=filer downloader_mgrno=downloader next_LS=downloader_LS;
run;

*Sanity check;
proc sort data=FBF5 nodupkey; by rdate filer downloader; run;

data copycat.copycat_fb; set FBF5; run;

if filer^=. and downloader^=. and filer_LS^=. and downloader_LS^=.;
if "31Dec2002"d<=rdate<="31Mar2017"d; run;

data copycat.copycat_ls; set LSF5; run;

data copy11; set copy10;
if filer_FB=1 or filer_LS=1 then filer_FBLS=1;
else filer_FBLS=0; run;

data copy12; set copy11;
if copycat^=.;
if download=. then download=0;
if robot=. then robot=0;
keep rdate filer downloader copycat download robot filer_FBLS;
run;

*Monthly stock returns;
data msf1; format RDATE yymmddn8.; Format MED yymmddn8.;
set crsp.msf (keep=permno date ret ALTPRC SHROUT);
where date between "&begdate"d and "&enddate"d;
RDATE = INTNX('QTR',date,-1,'E'); MED = INTNX('Month',date,0,'E');
ME = abs(ALTPRC)*SHROUT/1000; keep permno MED RDate ret ME;

*Part 2: LS stocks;
*The dataset LS12 can be created with SAS code "Copycat_CopycattingActivity";
data LS; set LS12; run;
